arguments.cmd:
cat > /app/output/styles.css <<'EOF'
:root {
  --bg: #000;
  --bg-soft: #141414;
  --panel: #191919;
  --panel-2: #242424;
  --text: #fff;
  --muted: #b8b8b8;
  --dim: #777;
  --red: #e50914;
  --red-deep: #b70710;
  --line: rgba(255, 255, 255, 0.14);
  --glow: rgba(229, 9, 20, 0.45);
  --radius: 22px;
  --max: 1180px;
  --font: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  min-width: 320px;
}

a { color: inherit; text-decoration: none; }

button, input, select { font: inherit; }

button { cursor: pointer; }

.site-shell {
  min-height: 100vh;
  overflow-x: hidden;
  background:
    radial-gradient(circle at 50% -10%, rgba(229, 9, 20, 0.24), transparent 38rem),
    linear-gradient(180deg, #050505 0%, #000 40%, #080808 100%);
}

.container {
  width: min(var(--max), calc(100% - 32px));
  margin: 0 auto;
}

.header {
  position: absolute;
  inset: 0 0 auto 0;
  z-index: 20;
  padding: 22px 0;
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.logo {
  color: var(--red);
  font-size: clamp(1.55rem, 4vw, 2.35rem);
  font-weight: 900;
  letter-spacing: -0.08em;
  text-transform: uppercase;
  text-shadow: 0 0 28px rgba(229, 9, 20, 0.28);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.language-select {
  min-height: 34px;
  color: var(--text);
  background: rgba(0, 0, 0, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.42);
  border-radius: 999px;
  padding: 7px 34px 7px 13px;
  outline: none;
  backdrop-filter: blur(12px);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 0;
  border-radius: 999px;
  min-height: 42px;
  padding: 0 18px;
  font-weight: 800;
  color: var(--text);
  transition: transform 160ms ease, background 160ms ease, box-shadow 160ms ease, border-color 160ms ease;
}

.btn:active { transform: scale(0.97); }

.btn-red {
  background: var(--red);
  box-shadow: 0 12px 36px rgba(229, 9, 20, 0.24);
}

.btn-red:hover, .btn-red:focus-visible {
  background: #f6121d;
  box-shadow: 0 15px 46px rgba(229, 9, 20, 0.38);
}

.btn-ghost {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--line);
}

.btn-ghost:hover, .btn-ghost:focus-visible {
  background: rgba(255, 255, 255, 0.14);
}

.hero {
  position: relative;
  min-height: 760px;
  display: grid;
  place-items: center;
  padding: 124px 0 84px;
  isolation: isolate;
  border-bottom: 8px solid #232323;
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -3;
  background:
    linear-gradient(103deg, rgba(20, 20, 20, 0.96) 0 22%, rgba(20, 20, 20, 0.55) 48%, rgba(20, 20, 20, 0.94) 100%),
    radial-gradient(circle at 50% 20%, rgba(229, 9, 20, 0.22), transparent 28rem),
    url("https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?auto=format&fit=crop&w=2200&q=80") center/cover;
  filter: saturate(1.18) contrast(1.08);
}

.hero::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -2;
  background:
    linear-gradient(180deg, rgba(0,0,0,0.52), rgba(0,0,0,0.1) 42%, rgba(0,0,0,0.78)),
    repeating-linear-gradient(90deg, rgba(255,255,255,0.03) 0 1px, transparent 1px 120px);
}

.poster-mosaic {
  position: absolute;
  inset: 95px max(-40px, calc((100vw - var(--max)) / 2 - 180px)) auto;
  z-index: -1;
  display: grid;
  grid-template-columns: repeat(6, minmax(88px, 1fr));
  gap: 14px;
  opacity: 0.42;
  transform: rotate(-7deg);
  pointer-events: none;
  mask-image: radial-gradient(ellipse at center, black 20%, transparent 72%);
}

.poster-chip {
  aspect-ratio: 2 / 3;
  border-radius: 14px;
  background: linear-gradient(145deg, var(--chip-a), var(--chip-b));
  border: 1px solid rgba(255,255,255,0.16);
  box-shadow: 0 16px 50px rgba(0,0,0,0.45);
}

.hero-content {
  max-width: 830px;
  text-align: center;
  animation: rise-in 560ms ease both;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin: 0 0 20px;
  padding: 8px 13px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 999px;
  background: rgba(0,0,0,0.42);
  color: #f2f2f2;
  font-size: 0.87rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  backdrop-filter: blur(10px);
}

.pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--red);
  box-shadow: 0 0 0 7px rgba(229, 9, 20, 0.18);
}

h1, h2, h3, p { margin-top: 0; }

.hero h1 {
  margin-bottom: 18px;
  font-size: clamp(2.8rem, 9vw, 5.9rem);
  line-height: 0.9;
  letter-spacing: -0.075em;
  font-weight: 950;
}

.hero .subtitle {
  margin-bottom: 14px;
  font-size: clamp(1.15rem, 2.4vw, 1.7rem);
  font-weight: 850;
}

.hero .prompt, .cta-panel .prompt {
  color: #f3f3f3;
  font-size: clamp(1rem, 1.8vw, 1.18rem);
  line-height: 1.55;
}

.signup-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  width: min(680px, 100%);
  margin: 22px auto 0;
}

.input-wrap { position: relative; }

.signup-form input, .login-form input {
  width: 100%;
  color: var(--text);
  background: rgba(18, 18, 18, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.38);
  border-radius: 10px;
  min-height: 58px;
  padding: 20px 16px 8px;
  outline: none;
  transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
}

.signup-form label, .login-field label {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: #c9c9c9;
  pointer-events: none;
  transition: 140ms ease;
}

.signup-form input:focus, .signup-form input:not(:placeholder-shown),
.login-form input:focus, .login-form input:not(:placeholder-shown) {
  border-color: rgba(255, 255, 255, 0.72);
  box-shadow: 0 0 0 3px rgba(229, 9, 20, 0.18);
  background: rgba(0, 0, 0, 0.72);
}

.signup-form input:focus + label, .signup-form input:not(:placeholder-shown) + label,
.login-form input:focus + label, .login-form input:not(:placeholder-shown) + label {
  top: 13px;
  transform: none;
  font-size: 0.75rem;
  color: #a8a8a8;
}

.btn-xl {
  min-height: 58px;
  border-radius: 10px;
  padding: 0 28px;
  font-size: clamp(1.05rem, 2vw, 1.42rem);
}

.section {
  padding: 56px 0;
  border-bottom: 8px solid #232323;
}

.section-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 22px;
}

.section h2 {
  margin: 0;
  font-size: clamp(1.7rem, 4vw, 2.8rem);
  letter-spacing: -0.055em;
  line-height: 1;
}

.section-kicker {
  margin: 10px 0 0;
  color: var(--muted);
  max-width: 620px;
}

.carousel-controls {
  display: flex;
  gap: 10px;
}

.arrow-btn {
  width: 48px;
  height: 48px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.09);
  color: var(--text);
  font-size: 1.6rem;
  transition: 160ms ease;
}

.arrow-btn:hover, .arrow-btn:focus-visible {
  background: var(--red);
  border-color: var(--red);
}

.trending-row {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: clamp(168px, 22vw, 232px);
  gap: 22px;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scroll-snap-type: inline mandatory;
  scroll-behavior: smooth;
  padding: 12px 4px 22px 16px;
  scrollbar-width: thin;
  scrollbar-color: #555 transparent;
}

.title-card {
  position: relative;
  min-height: 318px;
  border-radius: 18px;
  overflow: hidden;
  scroll-snap-align: start;
  background: linear-gradient(145deg, var(--poster-a), var(--poster-b));
  box-shadow: 0 20px 55px rgba(0,0,0,0.42);
  transform-origin: center;
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.title-card:hover {
  transform: translateY(-5px) scale(1.02);
  box-shadow: 0 24px 75px rgba(229,9,20,0.2);
}

.title-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 30% 18%, rgba(255,255,255,0.34), transparent 17%),
    linear-gradient(180deg, transparent 35%, rgba(0,0,0,0.86) 100%);
}

.rank {
  position: absolute;
  left: -12px;
  bottom: -26px;
  font-size: 8.2rem;
  line-height: 0.78;
  font-weight: 950;
  letter-spacing: -0.1em;
  color: rgba(255,255,255,0.07);
  -webkit-text-stroke: 2px rgba(255,255,255,0.42);
  text-shadow: 0 7px 22px rgba(0,0,0,0.75);
}

.title-card h3 {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 22px;
  margin: 0;
  font-size: 1.25rem;
  line-height: 1.05;
  letter-spacing: -0.04em;
}

.tag {
  position: absolute;
  top: 14px;
  left: 14px;
  padding: 5px 9px;
  border-radius: 999px;
  background: rgba(229, 9, 20, 0.86);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.feature-card {
  position: relative;
  min-height: 255px;
  padding: 24px;
  border-radius: var(--radius);
  overflow: hidden;
  background:
    radial-gradient(circle at 80% 100%, rgba(229, 9, 20, 0.28), transparent 36%),
    linear-gradient(145deg, #20132e, #131928 48%, #111);
  border: 1px solid rgba(255,255,255,0.1);
}

.feature-card h3 {
  margin-bottom: 12px;
  font-size: 1.32rem;
  letter-spacing: -0.05em;
}

.feature-card p {
  color: #cacada;
  line-height: 1.5;
}

.feature-icon {
  position: absolute;
  right: 22px;
  bottom: 20px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border-radius: 18px;
  background: linear-gradient(145deg, rgba(229,9,20,0.95), rgba(120,22,144,0.78));
  font-size: 1.7rem;
  box-shadow: 0 14px 34px rgba(0,0,0,0.35);
}

.faq-list {
  display: grid;
  gap: 9px;
}

.faq-item {
  background: #2d2d2d;
  border: 1px solid transparent;
  transition: background 160ms ease, border-color 160ms ease;
}

.faq-item:hover { background: #3a3a3a; }
.faq-item.open { border-color: rgba(255,255,255,0.18); }

.faq-question {
  width: 100%;
  min-height: 76px;
  padding: 22px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 18px;
  background: transparent;
  border: 0;
  color: var(--text);
  text-align: left;
  font-size: clamp(1.1rem, 2vw, 1.5rem);
}

.faq-plus {
  flex: 0 0 auto;
  font-size: 2.1rem;
  line-height: 1;
  transition: transform 220ms ease;
}

.faq-item.open .faq-plus { transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 260ms ease;
}

.faq-answer p {
  margin: 0;
  padding: 0 24px 24px;
  color: #ededed;
  font-size: 1.05rem;
  line-height: 1.55;
}

.cta-section {
  padding: 60px 0;
  border-bottom: 8px solid #232323;
}

.cta-panel {
  position: relative;
  overflow: hidden;
  border-radius: 30px;
  padding: clamp(28px, 6vw, 56px);
  text-align: center;
  background:
    radial-gradient(circle at 20% 10%, rgba(255,255,255,0.18), transparent 20rem),
    radial-gradient(circle at 82% 16%, rgba(229,9,20,0.55), transparent 22rem),
    linear-gradient(135deg, #271014, #070707 55%, #160607);
  border: 1px solid rgba(255,255,255,0.14);
  box-shadow: 0 28px 90px rgba(0,0,0,0.45);
}

.cta-panel h2 {
  margin-bottom: 12px;
}

.footer {
  color: rgba(255,255,255,0.72);
  padding: 42px 0 52px;
}

.footer a {
  text-decoration: underline;
  text-underline-offset: 2px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px 32px;
  margin: 26px 0;
  font-size: 0.93rem;
}

.legal-note {
  margin-top: 18px;
  color: var(--dim);
  font-size: 0.82rem;
}

.login-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background:
    linear-gradient(90deg, rgba(0,0,0,0.92), rgba(0,0,0,0.62), rgba(0,0,0,0.92)),
    url("https://images.unsplash.com/photo-1524985069026-dd778a71c7b4?auto=format&fit=crop&w=2200&q=80") center/cover;
}

.login-main {
  flex: 1;
  display: grid;
  place-items: center;
  padding: 116px 16px 56px;
}

.login-card {
  width: min(100%, 456px);
  padding: clamp(28px, 5vw, 48px);
  border-radius: 24px;
  background: rgba(0, 0, 0, 0.78);
  border: 1px solid rgba(255,255,255,0.12);
  box-shadow: 0 30px 90px rgba(0,0,0,0.62);
  backdrop-filter: blur(16px);
  animation: rise-in 420ms ease both;
}

.login-card h1 {
  margin-bottom: 10px;
  font-size: clamp(1.9rem, 5vw, 2.45rem);
  letter-spacing: -0.06em;
}

.login-card .subtext {
  margin-bottom: 26px;
  color: var(--muted);
}

.login-form {
  display: grid;
  gap: 14px;
}

.login-field { position: relative; }

.login-form .btn {
  width: 100%;
  min-height: 52px;
  margin-top: 6px;
  border-radius: 10px;
}

.form-note {
  margin: 4px 0 0;
  color: #9f9f9f;
  font-size: 0.9rem;
}

.help-toggle {
  width: 100%;
  display: flex;
  justify-content: space-between;
  margin-top: 22px;
  padding: 0;
  color: #fff;
  background: transparent;
  border: 0;
  font-weight: 800;
}

.help-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 220ms ease;
}

.help-panel ul {
  margin: 15px 0 0;
  padding-left: 18px;
  color: var(--muted);
  line-height: 1.7;
}

.login-footer {
  background: rgba(0,0,0,0.72);
}

@keyframes rise-in {
  from { opacity: 0; transform: translateY(22px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 1000px) {
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .poster-mosaic { grid-template-columns: repeat(4, 1fr); opacity: 0.3; }
}

@media (max-width: 720px) {
  .container { width: min(100% - 24px, var(--max)); }
  .header { padding: 18px 0; }
  .logo { letter-spacing: -0.07em; }
  .language-select { max-width: 104px; }
  .btn { min-height: 36px; padding-inline: 13px; }
  .hero { min-height: 690px; padding-top: 104px; }
  .hero h1 { letter-spacing: -0.065em; }
  .signup-form { grid-template-columns: 1fr; }
  .btn-xl { width: 100%; }
  .section { padding: 42px 0; }
  .section-header { align-items: start; }
  .carousel-controls { display: none; }
  .trending-row { grid-auto-columns: 156px; gap: 14px; padding-left: 4px; }
  .title-card { min-height: 246px; border-radius: 15px; }
  .rank { font-size: 6.3rem; bottom: -19px; }
  .title-card h3 { font-size: 1.05rem; }
  .features-grid { grid-template-columns: 1fr; }
  .feature-card { min-height: 214px; }
  .faq-question { padding: 18px; min-height: 66px; }
  .faq-answer p { padding: 0 18px 20px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .login-main { padding-top: 98px; }
}

@media (max-width: 430px) {
  .nav-actions { gap: 7px; }
  .language-select { width: 88px; padding-left: 10px; }
  .hero { min-height: 650px; }
  .eyebrow { font-size: 0.74rem; }
  .footer-grid { grid-template-columns: 1fr; }
}
EOF

cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
