          <span class="poster-chip" style="--chip-a:#36210b;--chip-b:#f19a22"></span>
          <span class="poster-chip" style="--chip-a:#12281c;--chip-b:#19b56d"></span>
          <span class="poster-chip" style="--chip-a:#32111e;--chip-b:#f03d7f"></span>
