          <span class="poster-chip" style="--chip-a:#25070b;--chip-b:#d1001f"></span>
          <span class="poster-chip" style="--chip-a:#1a1435;--chip-b:#aa4cff"></span>
          <span class="poster-chip" style="--chip-a:#33240e;--chip-b:#c78b23"></span>
          <span class="poster-chip" style="--chip-a:#0f2d30;--chip-b:#15b9c7"></span>
          <span class="poster-chip" style="--chip-a:#270a28;--chip-b:#e040fb"></span>
        </div>
        <div class="container hero-content">
          <p class="eyebrow"><span class="pulse-dot" aria-hidden="true"></span>Premium cinema at home</p>
