            <div class="carousel-controls" aria-label="Trending carousel controls">
              <button class="arrow-btn" type="button" data-carousel-prev aria-label="Scroll trending titles left">‹</button>
              <button class="arrow-btn" type="button" data-carousel-next aria-label="Scroll trending titles right">›</button>
